import { useMemo, useState } from 'react';
import { atoms, generateSigmaAlgebra, members } from '../../../lib/measure/index.ts';
import { DATA_COLORS } from '../../core/colors.ts';
import { FormulaLine } from '../../core/FormulaLine.tsx';
import { usePlayback } from '../../core/usePlayback.ts';
import { VizFrame } from '../../core/VizFrame.tsx';
import styles from './MeasureLab.module.css';

const STEPS_PER_SECOND = 0.7;

interface SigmaViewProps {
  title: string;
  points: number;
  generators: readonly (readonly number[])[];
  labels?: readonly string[];
}

/**
 * Sigma-algebra generated by a few subsets of a finite set. Each set is drawn
 * as a row of cells, one per point, filled when the point belongs to it. The
 * animation closes the family round by round under complements and unions;
 * the sets added in the current round are highlighted, and at the end the
 * atoms, the smallest non-empty sets, are marked.
 */
export function SigmaView({ title, points, generators, labels }: SigmaViewProps) {
  const names = labels ?? Array.from({ length: points }, (_, i) => String.fromCharCode(97 + i));
  const masks = useMemo(
    () => generators.map((g) => g.reduce((mask, i) => mask | (1 << i), 0)),
    [generators],
  );
  const rounds = useMemo(() => generateSigmaAlgebra(points, masks), [points, masks]);
  const [step, setStep] = useState(0);
  const last = rounds.length - 1;
  const playback = usePlayback({
    step: () => setStep((value) => Math.min(last, value + 1)),
    reset: () => setStep(0),
    rate: STEPS_PER_SECOND,
    done: step >= last,
  });
  const round = rounds[Math.min(step, last)] ?? { sets: [], added: [] };
  const finished = step >= last;
  const atomList = finished ? atoms(round.sets) : [];
  const show = (mask: number) => {
    const list = members(mask, points).map((i) => names[i]);
    return list.length === 0 ? '∅' : `{${list.join(', ')}}`;
  };
  const description = finished
    ? `La sigma-álgebra generada tiene ${round.sets.length} conjuntos y ${atomList.length} átomos: ${atomList.map(show).join(', ')}. ` +
      `Cada conjunto es una unión de átomos, por eso hay 2 elevado a ${atomList.length} conjuntos.`
    : `Ronda ${step}: la familia tiene ${round.sets.length} conjuntos; se agregaron ${round.added.map(show).join(', ')}.`;

  return (
    <VizFrame
      title={title}
      playback={playback}
      readouts={[
        { label: 'Ronda', value: `${step} de ${last}` },
        {
          label: 'Conjuntos en la familia',
          value: String(round.sets.length),
          color: DATA_COLORS.highlight,
        },
        { label: 'Átomos', value: finished ? String(atomList.length) : 'al terminar' },
        { label: 'Subconjuntos posibles', value: String(2 ** points) },
      ]}
      legend={[
        { label: 'Punto que pertenece al conjunto', color: DATA_COLORS.primary },
        { label: 'Agregado en esta ronda', color: DATA_COLORS.highlight },
      ]}
      description={description}
      graphic="html"
    >
      <FormulaLine
        tex={
          finished
            ? `|\\sigma(\\mathcal{G})| = 2^{${atomList.length}} = ${round.sets.length},\\quad \\text{átomos: } ${atomList.map((a) => show(a).replace(/[{}]/g, (c) => `\\${c}`)).join(',\\ ')}`
            : step === 0
              ? `\\mathcal{F}_0 = \\mathcal{G} \\cup \\{\\varnothing, \\Omega\\},\\quad |\\mathcal{F}_0| = ${round.sets.length}`
              : `\\mathcal{F}_{${step}} = \\mathcal{F}_{${Math.max(0, step - 1)}} \\cup \\{A^c,\\ A \\cup B : A, B \\in \\mathcal{F}_{${Math.max(0, step - 1)}}\\},\\quad |\\mathcal{F}_{${step}}| = ${round.sets.length}`
        }
      />
      <div className={styles.sets} aria-hidden="true">
        {round.sets.map((mask) => {
          const isNew = step > 0 && round.added.includes(mask);
          const isAtom = atomList.includes(mask);
          return (
            <div
              key={mask}
              className={`${styles.set} ${isNew ? styles.setNew : ''} ${isAtom ? styles.setAtom : ''}`}
            >
              <span className={styles.cells}>
                {names.map((_, i) => (
                  <span
                    key={i}
                    className={`${styles.cell} ${(mask >> i) & 1 ? styles.cellOn : ''}`}
                  />
                ))}
              </span>
              <span className={styles.setName}>{show(mask)}</span>
            </div>
          );
        })}
      </div>
    </VizFrame>
  );
}
